# Runs INSIDE Freya code nodes (code_exec sandbox: json, re, datetime) and in local tests.
# Rules for this file: stdlib only, never raise to the caller, and never two braces in a row
# (the platform may treat them as a template placeholder).
import datetime
import json
import re

WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
MONTHS = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
]


def parse_now(now):
    s = str(now or "").strip().replace(" ", "T")
    try:
        return datetime.datetime.fromisoformat(s[:16])
    except Exception:
        try:
            return datetime.datetime.fromisoformat(s[:10] + "T00:00")
        except Exception:
            return None


def say_date(d):
    return WEEKDAYS[d.weekday()] + " " + str(d.day) + " " + MONTHS[d.month - 1] + " " + str(d.year)


def is_business_day(d, cfg):
    workdays = cfg.get("workdays") or [0, 1, 2, 3, 4]
    return d.weekday() in workdays and d.isoformat() not in set(cfg.get("holidays") or [])


def next_business_day_on_or_after(d, cfg):
    for _ in range(60):
        if is_business_day(d, cfg):
            return d
        d = d + datetime.timedelta(days=1)
    return d


def nth_business_day_after(today, n, cfg):
    d = today
    count = 0
    for _ in range(400):
        d = d + datetime.timedelta(days=1)
        if is_business_day(d, cfg):
            count += 1
            if count >= n:
                return d
    return d


def prev_business_day_on_or_before(d, cfg):
    for _ in range(60):
        if is_business_day(d, cfg):
            return d
        d = d - datetime.timedelta(days=1)
    return d


def deadline_for(today, band, cfg):
    """Band deadline: the Nth business day after today (`deadline_unit` "business", default),
    or N calendar days after today moved back to a business day ("calendar")."""
    n = int(band.get("deadline_business_days") or band.get("deadline_days") or 0)
    if str(band.get("deadline_unit") or "business") == "calendar":
        return prev_business_day_on_or_before(today + datetime.timedelta(days=n), cfg)
    return nth_business_day_after(today, n, cfg)


def attempt1_date(today, cfg):
    """Date of persuasion attempt 1 (CFG["attempt1"]):
    rule "last_business_day_of_week" (Brief A rule 30: this week's last business day, or next
    week's when today is that day or later), or rule "nth_business_day" with `n`."""
    a = cfg.get("attempt1") or dict()
    if str(a.get("rule") or "last_business_day_of_week") == "nth_business_day":
        return nth_business_day_after(today, int(a.get("n") or 1), cfg)
    this_last = last_business_day_of_week(today, cfg)
    if this_last is not None and this_last > today:
        return this_last
    return last_business_day_of_week(today + datetime.timedelta(days=7), cfg)


def last_business_day_of_week(d, cfg):
    monday = d - datetime.timedelta(days=d.weekday())
    best = None
    for i in range(7):
        day = monday + datetime.timedelta(days=i)
        if is_business_day(day, cfg):
            best = day
    return best


def band_for(days_late, cfg):
    try:
        n = int(float(days_late))
    except Exception:
        return None
    for b in cfg.get("bands") or []:
        lo = b.get("min_days_late")
        hi = b.get("max_days_late")
        if (lo is None or n >= lo) and (hi is None or n <= hi):
            return b
    return None


def calendar_facts(now, cfg):
    """Every date fact the agent needs, as strings (routing compares strings)."""
    out = {"calendar_state": "unknown"}
    dt = parse_now(now)
    if dt is None:
        return out
    today = dt.date()
    out["calendar_state"] = "known"
    out["today_iso"] = today.isoformat()
    out["today_text"] = say_date(today)
    out["now_time"] = dt.strftime("%H:%M")
    out["today_is_business_day"] = "yes" if is_business_day(today, cfg) else "no"
    this_last = last_business_day_of_week(today, cfg)
    next_last = last_business_day_of_week(today + datetime.timedelta(days=7), cfg)
    out["last_business_day_this_week"] = this_last.isoformat() if this_last else ""
    out["last_business_day_next_week"] = next_last.isoformat() if next_last else ""
    a1 = attempt1_date(today, cfg)
    out["attempt1_date"] = a1.isoformat() if a1 else ""
    out["attempt1_date_text"] = say_date(a1) if a1 else ""
    for b in cfg.get("bands") or []:
        dl = deadline_for(today, b, cfg)
        key = "deadline_" + str(b.get("name"))
        out[key] = dl.isoformat()
        out[key + "_text"] = say_date(dl)
    # Callback window (third party).
    cb = cfg.get("callback") or {}
    start = str(cb.get("start") or "10:00")
    end = str(cb.get("end") or "19:00")
    # CFG["callback"]: include_today (default true), business_days_ahead (default 1),
    # business_days_only (default true: a callback day must be a business day).
    days = []
    bd_only = cb.get("business_days_only", True) is not False
    if cb.get("include_today", True) is not False and out["now_time"] < end:
        if is_business_day(today, cfg) or not bd_only:
            days.append(("today", today, max(start, out["now_time"])))
    for n in range(1, int(cb.get("business_days_ahead") or 1) + 1):
        nb = (
            nth_business_day_after(today, n, cfg)
            if bd_only
            else today + datetime.timedelta(days=n)
        )
        days.append(("next business day" if n == 1 else say_date(nb), nb, start))
    out["callback_window_text"] = " or ".join(
        name + " (" + say_date(d) + ", " + d.isoformat() + ") from " + s + " to " + end
        for name, d, s in days
    )
    out["callback_days"] = ",".join(d.isoformat() for _, d, _ in days)
    # A table of the coming days so the model never computes a date itself.
    monday = today - datetime.timedelta(days=today.weekday())
    rows = []
    for i in range(0, 28):
        d = today + datetime.timedelta(days=i)
        labels = []
        if i == 0:
            labels.append("today")
        if i == 1:
            labels.append("tomorrow")
        week = (d - monday).days // 7
        if week == 0:
            labels.append("this " + WEEKDAYS[d.weekday()])
        elif week == 1:
            labels.append("next " + WEEKDAYS[d.weekday()])
        status = (
            "business day"
            if is_business_day(d, cfg)
            else ("holiday" if d.isoformat() in set(cfg.get("holidays") or []) else "weekend")
        )
        rows.append(
            say_date(d)
            + " = "
            + d.isoformat()
            + " ("
            + status
            + ")"
            + (" [" + ", ".join(labels) + "]" if labels else "")
        )
    out["date_table"] = "\n".join(rows)
    return out


def load_products(raw):
    """get_account products arrive as a list, a JSON string or a python repr string."""
    if isinstance(raw, list):
        return [p for p in raw if isinstance(p, dict)]
    if isinstance(raw, str) and raw.strip():
        for loader in (
            json.loads,
            lambda s: json.loads(
                s.replace("'", '"')
                .replace("True", "true")
                .replace("False", "false")
                .replace("None", "null")
            ),
        ):
            try:
                v = loader(raw)
                if isinstance(v, list):
                    return [p for p in v if isinstance(p, dict)]
                if isinstance(v, dict) and isinstance(v.get("products"), list):
                    return [p for p in v["products"] if isinstance(p, dict)]
            except Exception:
                pass
    return []


def money(x):
    try:
        return "%.2f" % float(x)  # noqa: UP031
    except Exception:
        return str(x)


def product_facts(products, now, cfg):
    dt = parse_now(now)
    today = dt.date() if dt else None
    out = {
        "product_count": str(len(products)),
        "products_state": "known" if products else "unknown",
    }
    lines = []
    # CFG["product_fields"]: the names the tool API uses for these roles (hidden briefs can
    # rename them).
    fmap = cfg.get("product_fields") or dict()

    def pf(p, role):
        return p.get(fmap.get(role) or role)

    for i, p in enumerate(products):
        k = "p" + str(i + 1)
        ptype = str(pf(p, "type") or "")
        floor_field = (cfg.get("floor_field") or {}).get(ptype, "")
        floor = p.get(floor_field) if floor_field else None
        name_tpl = (cfg.get("product_names") or {}).get(ptype) or ptype.replace("_", " ")
        try:
            spoken = name_tpl.format(**{kk: str(vv) for kk, vv in p.items()})
        except Exception:
            spoken = ptype.replace("_", " ")
        band = band_for(pf(p, "days_late"), cfg)
        deadline = ""
        attempts = ""
        if band is not None and today is not None:
            deadline = deadline_for(today, band, cfg).isoformat()
            attempts = str(band.get("attempts") or "")
        out[k + "_id"] = str(pf(p, "product_id") or "")
        out[k + "_name"] = spoken
        out[k + "_past_due"] = money(pf(p, "past_due"))
        dl = pf(p, "days_late")
        try:
            dl = str(int(float(dl))) if float(dl) == int(float(dl)) else str(dl)
        except Exception:
            dl = str(dl or "")
        out[k + "_days_late"] = dl
        out[k + "_floor"] = money(floor) if floor is not None else ""
        out[k + "_band"] = str(band.get("name")) if band else ""
        out[k + "_deadline"] = deadline
        out[k + "_attempts"] = attempts
        lines.append(
            "Product "
            + str(i + 1)
            + ": "
            + spoken
            + " (product_id "
            + out[k + "_id"]
            + "), past due "
            + out[k + "_past_due"]
            + ", "
            + out[k + "_days_late"]
            + " days late"
            + (", floor " + out[k + "_floor"] if out[k + "_floor"] else "")
            + (
                ", latest promise date "
                + deadline
                + " ("
                + say_date(datetime.date.fromisoformat(deadline))
                + ")"
                if deadline
                else ""
            )
            + (", persuasion attempts " + attempts if attempts else "")
        )
    out["product_facts"] = "\n".join(lines)
    # What the model may say about the products: no floor, deadline or attempt count, so it
    # cannot make an offer of its own.
    out["product_brief"] = "\n".join(
        out["p" + str(i + 1) + "_name"]
        + ": "
        + out["p" + str(i + 1) + "_past_due"]
        + " past due, "
        + out["p" + str(i + 1) + "_days_late"]
        + " days late"
        for i in range(len(products))
    )
    return out


def check_promise_date(date_iso, deadline_iso, now, cfg):
    """'ok' | 'past' | 'not_business_day:<next bd>' | 'after_deadline:<deadline>' | 'unreadable'."""
    dt = parse_now(now)
    try:
        d = datetime.date.fromisoformat(str(date_iso)[:10])
        dl = datetime.date.fromisoformat(str(deadline_iso)[:10])
    except Exception:
        return "unreadable"
    if dt is None:
        return "unreadable"
    today = dt.date()
    if d < today:
        return "past"
    if d > dl:
        return "after_deadline:" + dl.isoformat()
    if not is_business_day(d, cfg):
        nb = next_business_day_on_or_after(d, cfg)
        if nb > dl:
            return "after_deadline:" + dl.isoformat()
        return "not_business_day:" + nb.isoformat()
    return "ok"


_WORD_MONTHS = dict((m.lower(), i + 1) for i, m in enumerate(MONTHS))
_WORD_MONTHS.update(dict((m[:3].lower(), i + 1) for i, m in enumerate(MONTHS)))


def normalize_dob(text):
    """'14 March 1988', 'March 14th, 1988', '14/03/1988' (day first), '1988-03-14' -> ISO."""
    s = str(text or "").strip().lower().replace(",", " ")
    m = re.match(r"^(\d{4})-(\d{1,2})-(\d{1,2})$", s)
    if m:
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
    else:
        nums = re.findall(r"\d+", s)
        mon = None
        for w in re.findall(r"[a-z]+", s):
            if w in _WORD_MONTHS:
                mon = _WORD_MONTHS[w]
        if mon and len(nums) >= 2:
            d, y, mo = int(nums[0]), int(nums[-1]), mon
        elif len(nums) == 3:
            d, mo, y = int(nums[0]), int(nums[1]), int(nums[2])
        else:
            return s
    if y < 100:
        y += 1900 if y > 30 else 2000
    try:
        return datetime.date(y, mo, d).isoformat()
    except Exception:
        return s


def find_products(v):
    """get_account products, wherever the platform put them: the mapped variable, a
    flattened `<x>.data.products` key, or one flattened key per field."""
    for key in ["products"] + [k for k in v if str(k).endswith(".data.products")]:
        got = load_products(v.get(key))
        if got:
            return got
    rows = {}
    for k in list(v):
        m = re.search(r"\.data\.products[.\[](\d+)\]?\.(\w+)$", str(k))
        if m:
            rows.setdefault(int(m.group(1)), {})[m.group(2)] = v[k]
    out = []
    for i in sorted(rows):
        p = rows[i]
        for f in ("past_due", "days_late", "minimum_payment", "instalment_amount"):
            if f in p:
                try:  # noqa: SIM105  (the sandbox's module list is not documented)
                    p[f] = float(p[f])
                except Exception:
                    pass
        out.append(p)
    return out


# Runs INSIDE Freya code nodes and in local tests. Stdlib only (json, re, datetime), never
# raises to the caller, never two braces in a row.
# Turns what a customer said into an ISO date relative to the call's `now` (the platform's
# extractor anchors dates to the real clock, not to `now`) and into an amount.
import datetime
import re

_MONTHS = [
    "january",
    "february",
    "march",
    "april",
    "may",
    "june",
    "july",
    "august",
    "september",
    "october",
    "november",
    "december",
]
_WDAYS = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]
_UNITS = {
    "zero": 0,
    "oh": 0,
    "one": 1,
    "two": 2,
    "three": 3,
    "four": 4,
    "five": 5,
    "six": 6,
    "seven": 7,
    "eight": 8,
    "nine": 9,
    "ten": 10,
    "eleven": 11,
    "twelve": 12,
    "thirteen": 13,
    "fourteen": 14,
    "fifteen": 15,
    "sixteen": 16,
    "seventeen": 17,
    "eighteen": 18,
    "nineteen": 19,
}
_TENS = {
    "twenty": 20,
    "thirty": 30,
    "forty": 40,
    "fifty": 50,
    "sixty": 60,
    "seventy": 70,
    "eighty": 80,
    "ninety": 90,
}
_ORD = {
    "first": 1,
    "second": 2,
    "third": 3,
    "fourth": 4,
    "fifth": 5,
    "sixth": 6,
    "seventh": 7,
    "eighth": 8,
    "ninth": 9,
    "tenth": 10,
    "eleventh": 11,
    "twelfth": 12,
    "thirteenth": 13,
    "fourteenth": 14,
    "fifteenth": 15,
    "sixteenth": 16,
    "seventeenth": 17,
    "eighteenth": 18,
    "nineteenth": 19,
    "twentieth": 20,
    "thirtieth": 30,
}
_VAGUE = [
    "next week",
    "week after next",
    "end of the month",
    "end of month",
    "end of the week",
    "salary",
    "payday",
    "pay day",
    "paid next",
    "get paid",
    "soon",
    "later this month",
    "next month",
    "in a few days",
    "in two weeks",
    "couple of weeks",
    "a few weeks",
    "sometime",
    "some time",
    "when i can",
    "beginning of",
    "middle of",
    "mid ",
]
_CORRECTION = re.compile(
    r"\b(?:sorry|i mean|no wait|wait|actually|rather|correction|make that|scratch that)\b"
)


def _words_to_number_tokens(s):
    """'twenty-second' -> '22nd', 'thirty first' -> '31st', 'four hundred and fifty-five'
    -> '455'. Leaves other text alone."""
    s = s.replace("-", " ")
    toks = s.split()
    out = []
    i = 0
    while i < len(toks):
        t = toks[i]
        if t in _TENS and i + 1 < len(toks) and toks[i + 1] in _ORD and _ORD[toks[i + 1]] < 10:
            out.append(str(_TENS[t] + _ORD[toks[i + 1]]) + "th")
            i += 2
            continue
        if t in _ORD:
            out.append(str(_ORD[t]) + "th")
            i += 1
            continue
        if (
            t in _UNITS
            or t in _TENS
            or (t == "a" and i + 1 < len(toks) and toks[i + 1] in ("hundred", "thousand"))
        ):
            total = 0
            cur = 0
            j = i
            used = False
            while j < len(toks):
                w = toks[j]
                if w in _UNITS:
                    if cur % 10 or (cur % 100 and _UNITS[w] >= 10):
                        break  # 'thirty seven fifty': a new number starts
                    cur += _UNITS[w]
                elif w in _TENS:
                    if cur % 100:
                        break
                    cur += _TENS[w]
                elif w == "a" and j + 1 < len(toks) and toks[j + 1] in ("hundred", "thousand"):
                    cur += 1
                elif w == "hundred":
                    cur = max(cur, 1) * 100
                elif w == "thousand":
                    total += max(cur, 1) * 1000
                    cur = 0
                elif (
                    w == "and"
                    and used
                    and j + 1 < len(toks)
                    and (toks[j + 1] in _UNITS or toks[j + 1] in _TENS)
                ):
                    pass
                else:
                    break
                used = True
                j += 1
            out.append(str(total + cur))
            i = j
            continue
        out.append(t)
        i += 1
    return " ".join(out)


def _norm_text(text):
    s = str(text or "").lower()
    s = s.replace(",", " ").replace("’", "'")
    s = re.sub(r"(\d)(st|nd|rd|th)\b", r"\1", s)
    s = _words_to_number_tokens(s)
    s = re.sub(r"(\d+)(st|nd|rd|th)\b", r"\1", s)
    return re.sub(r"\s+", " ", s).strip()


_NUMWORD = "|".join(list(_UNITS) + list(_TENS) + list(_ORD) + ["hundred", "thousand"])


def _last_segment(s):
    """After 'sorry, I mean ...' the last part that holds a value wins."""
    parts = _CORRECTION.split(s)
    for p in reversed(parts):
        if re.search(r"\d|\b(?:" + _NUMWORD + "|" + "|".join(_WDAYS) + r"|today|tomorrow)\b", p):
            return p
    return s


def _month_of(word):
    for i, m in enumerate(_MONTHS):
        if word == m or (len(word) >= 3 and m.startswith(word)):
            return i + 1
    return None


def _safe_date(y, m, d):
    try:
        return datetime.date(y, m, d)
    except Exception:
        return None


def parse_spoken_date(text, today):
    """-> (iso or '', 'vague' | 'date' | 'none'). `today` is a datetime.date."""
    iso = re.findall(r"\b(\d{4})-(\d{1,2})-(\d{1,2})\b", str(text or ""))
    if iso:
        y, mo, dd = iso[-1]
        d = _safe_date(int(y), int(mo), int(dd))
        return (d.isoformat(), "date") if d else ("", "none")
    raw = _norm_text(text)
    if not raw:
        return "", "none"
    s = _last_segment(raw)
    if "day after tomorrow" in s:
        return (today + datetime.timedelta(days=2)).isoformat(), "date"
    if "tomorrow" in s:
        return (today + datetime.timedelta(days=1)).isoformat(), "date"
    if re.search(r"\btoday\b|\bright now\b|\bnow\b", s) and not re.search(r"\d", s):
        return today.isoformat(), "date"
    # day + month name, either order
    toks = s.split()
    day = None
    month = None
    year = None
    for i, t in enumerate(toks):
        mo = _month_of(t) if re.fullmatch(r"[a-z]+", t) else None
        if (mo and t not in ("may",)) or (
            t == "may" and i > 0 and re.fullmatch(r"\d{1,2}", toks[i - 1] or "")
        ):
            month = mo
            if i > 0 and re.fullmatch(r"\d{1,2}", toks[i - 1]):
                day = int(toks[i - 1])
            elif i > 1 and toks[i - 1] == "of" and re.fullmatch(r"\d{1,2}", toks[i - 2]):
                day = int(toks[i - 2])
            elif i + 1 < len(toks) and re.fullmatch(r"\d{1,2}", toks[i + 1]):
                day = int(toks[i + 1])
            if i + 1 < len(toks) and re.fullmatch(r"\d{4}", toks[-1]):
                year = int(toks[-1])
    m = re.search(r"\b(\d{1,2})[/.](\d{1,2})(?:[/.](\d{2,4}))?\b", s)
    if month is None and m:
        day, month = int(m.group(1)), int(m.group(2))
        if m.group(3):
            year = int(m.group(3)) + (2000 if len(m.group(3)) == 2 else 0)
    if month and day:
        y = year or today.year
        d = _safe_date(y, month, day)
        if d and not year and d < today:
            d = _safe_date(y + 1, month, day)
        return (d.isoformat(), "date") if d else ("", "none")
    # weekday, with this / next
    for i, w in enumerate(_WDAYS):
        if re.search(r"\b" + w + r"\b", s):
            monday = today - datetime.timedelta(days=today.weekday())
            this_day = monday + datetime.timedelta(days=i)
            if re.search(r"\bnext\s+" + w, s) or "following" in s:
                d = this_day + datetime.timedelta(days=7)
            elif re.search(r"\bthis\s+" + w, s) or re.search(r"\bthis coming\s+" + w, s):
                d = this_day
            else:
                d = this_day if this_day >= today else this_day + datetime.timedelta(days=7)
            num = re.search(r"\b(\d{1,2})\b", s)
            if num:
                # 'Monday the 26th': trust the number, it is more specific
                n = int(num.group(1))
                dd = _safe_date(today.year, today.month, n) if 1 <= n <= 31 else None
                if dd and dd < today:
                    nm = today.month % 12 + 1
                    dd = _safe_date(today.year + (1 if nm == 1 else 0), nm, n)
                if dd:
                    return dd.isoformat(), "date"
            return d.isoformat(), "date"
    # 'the 26th' alone
    m = re.search(r"\b(?:the\s+)?(\d{1,2})\b", s)
    if (m and any(v in raw for v in ("the ",))) or (
        m and re.fullmatch(r"(?:on\s+)?(?:the\s+)?\d{1,2}", s)
    ):
        n = int(m.group(1))
        if 1 <= n <= 31:
            d = _safe_date(today.year, today.month, n)
            if d is None or d < today:
                nm = today.month % 12 + 1
                d = _safe_date(today.year + (1 if nm == 1 else 0), nm, n)
            if d:
                return d.isoformat(), "date"
    for v in _VAGUE:
        if v in raw:
            return "", "vague"
    return "", "none"


def parse_amount(text):
    """'637.50', '637,50', 'six hundred and thirty-seven fifty', 'two thousand one hundred
    twenty-five pounds and ten pence' -> float, or None."""
    raw = str(text or "").lower().replace("’", "'")
    raw = re.sub(r"(\d),(\d{2})(?!\d)", r"\1.\2", raw)
    if not raw.strip():
        return None
    s = _last_segment(raw)
    m = re.search(r"(\d[\d ,]*\d|\d)(?:[.,](\d{1,2}))?(?!\d)", s)
    if m and not re.search(
        r"[a-z]", re.sub(r"(pounds?|euros?|dollars?|eur|gbp|usd|and|cents?|pence|p\b)", "", s)
    ):
        whole = re.sub(r"[ ,]", "", m.group(1))
        frac = m.group(2) or ""
        try:
            return float(whole + ("." + frac if frac else ""))
        except Exception:
            return None
    s2 = re.sub(r"\b(pounds?|euros?|dollars?)\b", " | ", s)
    s2 = re.sub(r"\b(cents?|pence|p)\b", " ", s2)
    s2 = re.sub(r"\bpoint\b", " | ", s2)
    parts = [p for p in s2.split("|")]
    nums = []
    for p in parts:
        t = _words_to_number_tokens(p.replace("-", " "))
        found = re.findall(r"\d+(?:\.\d+)?", t)
        if found:
            nums.append(found)
    if not nums:
        return None
    try:
        whole = float(nums[0][0]) if len(nums[0]) == 1 else float("".join(nums[0]))
        if len(nums) > 1:
            cents = nums[1][0]
            if "point" in s and len(cents) == 1:
                return whole + float("0." + cents)
            return whole + float(cents) / 100.0
        if len(nums[0]) == 2 and float(nums[0][1]) < 100:
            # 'six hundred thirty seven fifty' -> 637.50
            return float(nums[0][0]) + float(nums[0][1]) / 100.0
        return whole
    except Exception:
        return None


def parse_spoken_time(text, day_start=10, day_end=19):
    """'around eleven', '11am', 'half past two', '14:30', 'two thirty in the afternoon' ->
    'HH:MM', or ''. A bare hour that cannot be a working hour as said (1 to 7) is read as
    afternoon; 'morning' / 'afternoon' / 'evening' / am / pm decide when given."""
    raw = str(text or "").lower().replace(".", " ").replace("-", " ")
    if not raw.strip():
        return ""
    s = re.sub(r"(\d)([a-z])", r"\1 \2", _last_segment(raw))
    if "noon" in s and "after" not in s:
        return "12:00"
    pm = bool(re.search(r"\b(pm|p m|afternoon|evening|tonight)\b", s))
    am = bool(re.search(r"\b(am|a m|morning)\b", s))
    s = re.sub(r"\b(o'?clock|oclock|ish|around|about|at|by|maybe)\b", " ", s)
    t = _words_to_number_tokens(s)
    hour, minute = None, 0
    m = re.search(r"\b(\d{1,2})[:h ](\d{2})\b", t)
    if m and int(m.group(2)) < 60:
        hour, minute = int(m.group(1)), int(m.group(2))
    else:
        m = re.search(r"\bhalf past (\d{1,2})\b", t)
        q = re.search(r"\bquarter past (\d{1,2})\b", t)
        q2 = re.search(r"\bquarter to (\d{1,2})\b", t)
        if m:
            hour, minute = int(m.group(1)), 30
        elif q:
            hour, minute = int(q.group(1)), 15
        elif q2:
            hour, minute = int(q2.group(1)) - 1, 45
        else:
            m = re.search(r"\b(\d{1,2}) (\d{2})\b", t)
            if m and int(m.group(2)) < 60 and int(m.group(1)) <= 23:
                hour, minute = int(m.group(1)), int(m.group(2))
            else:
                m = re.search(r"\b(\d{1,2})\b", t)
                if m:
                    hour = int(m.group(1))
    if hour is None or hour > 23:
        return ""
    if (pm and hour < 12) or (not am and 1 <= hour <= 7):
        hour += 12
    elif am and hour == 12:
        hour = 0
    return "%02d:%02d" % (hour, minute)


def digits_from_speech(text):
    """'four four seven one', '44 71', 'forty-four seventy-one' -> '4471'."""
    raw = str(text or "").lower().replace("-", " ")
    s = _last_segment(raw)
    out = []
    for w in re.findall(r"[a-z]+|\d+", s):
        if w.isdigit():
            out.append(w)
        elif w in ("oh", "o", "zero"):
            out.append("0")
        elif w in _UNITS:
            out.append(str(_UNITS[w]))
        elif w in _TENS:
            out.append(str(_TENS[w]))
        elif w in ("double", "triple"):
            out.append(w)
    # 'double four' -> '44'; 'forty four' -> '44' (a tens word followed by a unit)
    res = []
    i = 0
    while i < len(out):
        x = out[i]
        if x in ("double", "triple") and i + 1 < len(out):
            res.append(out[i + 1] * (2 if x == "double" else 3))
            i += 2
            continue
        if len(x) == 2 and x.endswith("0") and i + 1 < len(out) and len(out[i + 1]) == 1:
            res.append(x[0] + out[i + 1])
            i += 2
            continue
        res.append(x)
        i += 1
    return "".join(r for r in res if r.isdigit())


