Follow that instruction, in one or two short sentences. Do not call any tool. Never compute a date or an amount yourself and never name a date, an amount or a term that is not in the instruction. Never ask how much the customer can pay. Never offer a discount, a waiver or an instalment plan. If asked whether you are a robot or an AI: "I am Freya Bank's digital assistant." If asked whether this is a scam: "You can verify this call by phoning Freya Bank's customer service number." A question you cannot answer from the facts below: "I do not have that information."

Facts:
{{product_brief}}

code.default:
# Runs INSIDE Freya code nodes (code_exec sandbox: json, re, datetime) and in local tests.
# Rules for this file: stdlib only, never raise to the caller, and never two braces in a row
# (the platform may treat them as a template placeholder).
import datetime
import json
import re

WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
MONTHS = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
]


def parse_now(now):
    s = str(now or "").strip().replace(" ", "T")
    try:
        return datetime.datetime.fromisoformat(s[:16])
    except Exception:
        try:
            return datetime.datetime.fromisoformat(s[:10] + "T00:00")
        except Exception:
            return None


def say_date(d):
    return WEEKDAYS[d.weekday()] + " " + str(d.day) + " " + MONTHS[d.month - 1] + " " + str(d.year)


def is_business_day(d, cfg):
    workdays = cfg.get("workdays") or [0, 1, 2, 3, 4]
    return d.weekday() in workdays and d.isoformat() not in set(cfg.get("holidays") or [])


def next_business_day_on_or_after(d, cfg):
    for _ in range(60):
        if is_business_day(d, cfg):
            return d
        d = d + datetime.timedelta(days=1)
    return d


def nth_business_day_after(today, n, cfg):
    d = today
    count = 0
    for _ in range(400):
        d = d + datetime.timedelta(days=1)
        if is_business_day(d, cfg):
            count += 1
            if count >= n:
                return d
    return d


def prev_business_day_on_or_before(d, cfg):
    for _ in range(60):
        if is_business_day(d, cfg):
            return d
        d = d - datetime.timedelta(days=1)
    return d


def deadline_for(today, band, cfg):
    """Band deadline: the Nth business day after today (`deadline_unit` "business", default),
    or N calendar days after today moved back to a business day ("calendar")."""
    n = int(band.get("deadline_business_days") or band.get("deadline_days") or 0)
    if str(band.get("deadline_unit") or "business") == "calendar":
        return prev_business_day_on_or_before(today + datetime.timedelta(days=n), cfg)
    return nth_business_day_after(today, n, cfg)


def attempt1_date(today, cfg):
    """Date of persuasion attempt 1 (CFG["attempt1"]):
    rule "last_business_day_of_week" (Brief A rule 30: this week's last business day, or next
    week's when today is that day or later), or rule "nth_business_day" with `n`."""
    a = cfg.get("attempt1") or dict()
    if str(a.get("rule") or "last_business_day_of_week") == "nth_business_day":
        return nth_business_day_after(today, int(a.get("n") or 1), cfg)
    this_last = last_business_day_of_week(today, cfg)
    if this_last is not None and this_last > today:
        return this_last
    return last_business_day_of_week(today + datetime.timedelta(days=7), cfg)


def last_business_day_of_week(d, cfg):
    monday = d - datetime.timedelta(days=d.weekday())
    best = None
    for i in range(7):
        day = monday + datetime.timedelta(days=i)
        if is_business_day(day, cfg):
            best = day
    return best


def band_for(days_late, cfg):
    try:
        n = int(float(days_late))
    except Exception:
        return None
    for b in cfg.get("bands") or []:
        lo = b.get("min_days_late")
        hi = b.get("max_days_late")
        if (lo is None or n >= lo) and (hi is None or n <= hi):
            return b
    return None


def calendar_facts(now, cfg):
    """Every date fact the agent needs, as strings (routing compares strings)."""
    out = {"calendar_state": "unknown"}
    dt = parse_now(now)
    if dt is None:
        return out
    today = dt.date()
    out["calendar_state"] = "known"
    out["today_iso"] = today.isoformat()
    out["today_text"] = say_date(today)
    out["now_time"] = dt.strftime("%H:%M")
    out["today_is_business_day"] = "yes" if is_business_day(today, cfg) else "no"
    this_last = last_business_day_of_week(today, cfg)
    next_last = last_business_day_of_week(today + datetime.timedelta(days=7), cfg)
    out["last_business_day_this_week"] = this_last.isoformat() if this_last else ""
    out["last_business_day_next_week"] = next_last.isoformat() if next_last else ""
    a1 = attempt1_date(today, cfg)
    out["attempt1_date"] = a1.isoformat() if a1 else ""
    out["attempt1_date_text"] = say_date(a1) if a1 else ""
    for b in cfg.get("bands") or []:
        dl = deadline_for(today, b, cfg)
        key = "deadline_" + str(b.get("name"))
        out[key] = dl.isoformat()
        out[key + "_text"] = say_date(dl)
    # Callback window (third party).
    cb = cfg.get("callback") or {}
    start = str(cb.get("start") or "10:00")
    end = str(cb.get("end") or "19:00")
    # CFG["callback"]: include_today (default true), business_days_ahead (default 1),
    # business_days_only (default true: a callback day must be a business day).
    days = []
    bd_only = cb.get("business_days_only", True) is not False
    if cb.get("include_today", True) is not False and out["now_time"] < end:
        if is_business_day(today, cfg) or not bd_only:
            days.append(("today", today, max(start, out["now_time"])))
    for n in range(1, int(cb.get("business_days_ahead") or 1) + 1):
        nb = (
            nth_business_day_after(today, n, cfg)
            if bd_only
            else today + datetime.timedelta(days=n)
        )
        days.append(("next business day" if n == 1 else say_date(nb), nb, start))
    out["callback_window_text"] = " or ".join(
        name + " (" + say_date(d) + ", " + d.isoformat() + ") from " + s + " to " + end
        for name, d, s in days
    )
    out["callback_days"] = ",".join(d.isoformat() for _, d, _ in days)
    # A table of the coming days so the model never computes a date itself.
    monday = today - datetime.timedelta(days=today.weekday())
    rows = []
    for i in range(0, 28):
        d = today + datetime.timedelta(days=i)
        labels = []
        if i == 0:
            labels.append("today")
        if i == 1:
            labels.append("tomorrow")
        week = (d - monday).days // 7
        if week == 0:
            labels.append("this " + WEEKDAYS[d.weekday()])
        elif week == 1:
            labels.append("next " + WEEKDAYS[d.weekday()])
        status = (
            "business day"
            if is_business_day(d, cfg)
            else ("holiday" if d.isoformat() in set(cfg.get("holidays") or []) else "weekend")
        )
        rows.append(
            say_date(d)
            + " = "
            + d.isoformat()
            + " ("
            + status
            + ")"
            + (" [" + ", ".join(labels) + "]" if labels else "")
        )
    out["date_table"] = "\n".join(rows)
    return out


def load_products(raw):
    """get_account products arrive as a list, a JSON string or a python repr string."""
    if isinstance(raw, list):
        return [p for p in raw if isinstance(p, dict)]
    if isinstance(raw, str) and raw.strip():
        for loader in (
            json.loads,
            lambda s: json.loads(
                s.replace("'", '"')
                .replace("True", "true")
                .replace("False", "false")
                .replace("None", "null")
            ),
        ):
            try:
                v = loader(raw)
                if isinstance(v, list):
                    return [p for p in v if isinstance(p, dict)]
                if isinstance(v, dict) and isinstance(v.get("products"), list):
                    return [p for p in v["products"] if isinstance(p, dict)]
            except Exception:
                pass
    return []


def money(x):
    try:
        return "%.2f" % float(x)  # noqa: UP031
    except Exception:
        return str(x)


def product_facts(products, now, cfg):
    dt = parse_now(now)
    today = dt.date() if dt else None
    out = {
        "product_count": str(len(products)),
        "products_state": "known" if products else "unknown",
    }
    lines = []
    # CFG["product_fields"]: the names the tool API uses for these roles (hidden briefs can
    # rename them).
    fmap = cfg.get("product_fields") or dict()

    def pf(p, role):
        return p.get(fmap.get(role) or role)

    for i, p in enumerate(products):
        k = "p" + str(i + 1)
        ptype = str(pf(p, "type") or "")
        floor_field = (cfg.get("floor_field") or {}).get(ptype, "")
        floor = p.get(floor_field) if floor_field else None
        name_tpl = (cfg.get("product_names") or {}).get(ptype) or ptype.replace("_", " ")
        try:
            spoken = name_tpl.format(**{kk: str(vv) for kk, vv in p.items()})
        except Exception:
            spoken = ptype.replace("_", " ")
        band = band_for(pf(p, "days_late"), cfg)
        deadline = ""
        attempts = ""
        if band is not None and today is not None:
            deadline = deadline_for(today, band, cfg).isoformat()
            attempts = str(band.get("attempts") or "")
        out[k + "_id"] = str(pf(p, "product_id") or "")
        out[k + "_name"] = spoken
        out[k + "_past_due"] = money(pf(p, "past_due"))
        dl = pf(p, "days_late")
        try:
            dl = str(int(float(dl))) if float(dl) == int(float(dl)) else str(dl)
        except Exception:
            dl = str(dl or "")
        out[k + "_days_late"] = dl
        out[k + "_floor"] = money(floor) if floor is not None else ""
        out[k + "_band"] = str(band.get("name")) if band else ""
        out[k + "_deadline"] = deadline
        out[k + "_attempts"] = attempts
        lines.append(
            "Product "
            + str(i + 1)
            + ": "
            + spoken
            + " (product_id "
            + out[k + "_id"]
            + "), past due "
            + out[k + "_past_due"]
            + ", "
            + out[k + "_days_late"]
            + " days late"
            + (", floor " + out[k + "_floor"] if out[k + "_floor"] else "")
            + (
                ", latest promise date "
                + deadline
                + " ("
                + say_date(datetime.date.fromisoformat(deadline))
                + ")"
                if deadline
                else ""
            )
            + (", persuasion attempts " + attempts if attempts else "")
        )
    out["product_facts"] = "\n".join(lines)
    # What the model may say about the products: no floor, deadline or attempt count, so it
    # cannot make an offer of its own.
    out["product_brief"] = "\n".join(
        out["p" + str(i + 1) + "_name"]
        + ": "
        + out["p" + str(i + 1) + "_past_due"]
        + " past due, "
        + out["p" + str(i + 1) + "_days_late"]
        + " days late"
        for i in range(len(products))
    )
    return out


def check_promise_date(date_iso, deadline_iso, now, cfg):
    """'ok' | 'past' | 'not_business_day:<next bd>' | 'after_deadline:<deadline>' | 'unreadable'."""
    dt = parse_now(now)
    try:
        d = datetime.date.fromisoformat(str(date_iso)[:10])
        dl = datetime.date.fromisoformat(str(deadline_iso)[:10])
    except Exception:
        return "unreadable"
    if dt is None:
        return "unreadable"
    today = dt.date()
    if d < today:
        return "past"
    if d > dl:
        return "after_deadline:" + dl.isoformat()
    if not is_business_day(d, cfg):
        nb = next_business_day_on_or_after(d, cfg)
        if nb > dl:
            return "after_deadline:" + dl.isoformat()
        return "not_business_day:" + nb.isoformat()
    return "ok"


_WORD_MONTHS = dict((m.lower(), i + 1) for i, m in enumerate(MONTHS))
_WORD_MONTHS.update(dict((m[:3].lower(), i + 1) for i, m in enumerate(MONTHS)))


def normalize_dob(text):
    """'14 March 1988', 'March 14th, 1988', '14/03/1988' (day first), '1988-03-14' -> ISO."""
    s = str(text or "").strip().lower().replace(",", " ")
    m = re.match(r"^(\d{4})-(\d{1,2})-(\d{1,2})$", s)
    if m:
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
    else:
        nums = re.findall(r"\d+", s)
        mon = None
        for w in re.findall(r"[a-z]+", s):
            if w in _WORD_MONTHS:
                mon = _WORD_MONTHS[w]
        if mon and len(nums) >= 2:
            d, y, mo = int(nums[0]), int(nums[-1]), mon
        elif len(nums) == 3:
            d, mo, y = int(nums[0]), int(nums[1]), int(nums[2])
        else:
            return s
    if y < 100:
        y += 1900 if y > 30 else 2000
    try:
        return datetime.date(y, mo, d).isoformat()
    except Exception:
        return s


def find_products(v):
    """get_account products, wherever the platform put them: the mapped variable, a
    flattened `<x>.data.products` key, or one flattened key per field."""
    for key in ["products"] + [k for k in v if str(k).endswith(".data.products")]:
        got = load_products(v.get(key))
        if got:
            return got
    rows = {}
    for k in list(v):
        m = re.search(r"\.data\.products[.\[](\d+)\]?\.(\w+)$", str(k))
        if m:
            rows.setdefault(int(m.group(1)), {})[m.group(2)] = v[k]
    out = []
    for i in sorted(rows):
        p = rows[i]
        for f in ("past_due", "days_late", "minimum_payment", "instalment_amount"):
            if f in p:
                try:  # noqa: SIM105  (the sandbox's module list is not documented)
                    p[f] = float(p[f])
                except Exception:
                    pass
        out.append(p)
    return out


# Runs INSIDE Freya code nodes and in local tests. Stdlib only (json, re, datetime), never
# raises to the caller, never two braces in a row.
# Turns what a customer said into an ISO date relative to the call's `now` (the platform's
# extractor anchors dates to the real clock, not to `now`) and into an amount.
import datetime
import re

_MONTHS = [
    "january",
    "february",
    "march",
    "april",
    "may",
    "june",
    "july",
    "august",
    "september",
    "october",
    "november",
    "december",
]
_WDAYS = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]
_UNITS = {
    "zero": 0,
    "oh": 0,
    "one": 1,
    "two": 2,
    "three": 3,
    "four": 4,
    "five": 5,
    "six": 6,
    "seven": 7,
    "eight": 8,
    "nine": 9,
    "ten": 10,
    "eleven": 11,
    "twelve": 12,
    "thirteen": 13,
    "fourteen": 14,
    "fifteen": 15,
    "sixteen": 16,
    "seventeen": 17,
    "eighteen": 18,
    "nineteen": 19,
}
_TENS = {
    "twenty": 20,
    "thirty": 30,
    "forty": 40,
    "fifty": 50,
    "sixty": 60,
    "seventy": 70,
    "eighty": 80,
    "ninety": 90,
}
_ORD = {
    "first": 1,
    "second": 2,
    "third": 3,
    "fourth": 4,
    "fifth": 5,
    "sixth": 6,
    "seventh": 7,
    "eighth": 8,
    "ninth": 9,
    "tenth": 10,
    "eleventh": 11,
    "twelfth": 12,
    "thirteenth": 13,
    "fourteenth": 14,
    "fifteenth": 15,
    "sixteenth": 16,
    "seventeenth": 17,
    "eighteenth": 18,
    "nineteenth": 19,
    "twentieth": 20,
    "thirtieth": 30,
}
_VAGUE = [
    "next week",
    "week after next",
    "end of the month",
    "end of month",
    "end of the week",
    "salary",
    "payday",
    "pay day",
    "paid next",
    "get paid",
    "soon",
    "later this month",
    "next month",
    "in a few days",
    "in two weeks",
    "couple of weeks",
    "a few weeks",
    "sometime",
    "some time",
    "when i can",
    "beginning of",
    "middle of",
    "mid ",
]
_CORRECTION = re.compile(
    r"\b(?:sorry|i mean|no wait|wait|actually|rather|correction|make that|scratch that)\b"
)


def _words_to_number_tokens(s):
    """'twenty-second' -> '22nd', 'thirty first' -> '31st', 'four hundred and fifty-five'
    -> '455'. Leaves other text alone."""
    s = s.replace("-", " ")
    toks = s.split()
    out = []
    i = 0
    while i < len(toks):
        t = toks[i]
        if t in _TENS and i + 1 < len(toks) and toks[i + 1] in _ORD and _ORD[toks[i + 1]] < 10:
            out.append(str(_TENS[t] + _ORD[toks[i + 1]]) + "th")
            i += 2
            continue
        if t in _ORD:
            out.append(str(_ORD[t]) + "th")
            i += 1
            continue
        if (
            t in _UNITS
            or t in _TENS
            or (t == "a" and i + 1 < len(toks) and toks[i + 1] in ("hundred", "thousand"))
        ):
            total = 0
            cur = 0
            j = i
            used = False
            while j < len(toks):
                w = toks[j]
                if w in _UNITS:
                    if cur % 10 or (cur % 100 and _UNITS[w] >= 10):
                        break  # 'thirty seven fifty': a new number starts
                    cur += _UNITS[w]
                elif w in _TENS:
                    if cur % 100:
                        break
                    cur += _TENS[w]
                elif w == "a" and j + 1 < len(toks) and toks[j + 1] in ("hundred", "thousand"):
                    cur += 1
                elif w == "hundred":
                    cur = max(cur, 1) * 100
                elif w == "thousand":
                    total += max(cur, 1) * 1000
                    cur = 0
                elif (
                    w == "and"
                    and used
                    and j + 1 < len(toks)
                    and (toks[j + 1] in _UNITS or toks[j + 1] in _TENS)
                ):
                    pass
                else:
                    break
                used = True
                j += 1
            out.append(str(total + cur))
            i = j
            continue
        out.append(t)
        i += 1
    return " ".join(out)


def _norm_text(text):
    s = str(text or "").lower()
    s = s.replace(",", " ").replace("’", "'")
    s = re.sub(r"(\d)(st|nd|rd|th)\b", r"\1", s)
    s = _words_to_number_tokens(s)
    s = re.sub(r"(\d+)(st|nd|rd|th)\b", r"\1", s)
    return re.sub(r"\s+", " ", s).strip()


_NUMWORD = "|".join(list(_UNITS) + list(_TENS) + list(_ORD) + ["hundred", "thousand"])


def _last_segment(s):
    """After 'sorry, I mean ...' the last part that holds a value wins."""
    parts = _CORRECTION.split(s)
    for p in reversed(parts):
        if re.search(r"\d|\b(?:" + _NUMWORD + "|" + "|".join(_WDAYS) + r"|today|tomorrow)\b", p):
            return p
    return s


def _month_of(word):
    for i, m in enumerate(_MONTHS):
        if word == m or (len(word) >= 3 and m.startswith(word)):
            return i + 1
    return None


def _safe_date(y, m, d):
    try:
        return datetime.date(y, m, d)
    except Exception:
        return None


def parse_spoken_date(text, today):
    """-> (iso or '', 'vague' | 'date' | 'none'). `today` is a datetime.date."""
    iso = re.findall(r"\b(\d{4})-(\d{1,2})-(\d{1,2})\b", str(text or ""))
    if iso:
        y, mo, dd = iso[-1]
        d = _safe_date(int(y), int(mo), int(dd))
        return (d.isoformat(), "date") if d else ("", "none")
    raw = _norm_text(text)
    if not raw:
        return "", "none"
    s = _last_segment(raw)
    if "day after tomorrow" in s:
        return (today + datetime.timedelta(days=2)).isoformat(), "date"
    if "tomorrow" in s:
        return (today + datetime.timedelta(days=1)).isoformat(), "date"
    if re.search(r"\btoday\b|\bright now\b|\bnow\b", s) and not re.search(r"\d", s):
        return today.isoformat(), "date"
    # day + month name, either order
    toks = s.split()
    day = None
    month = None
    year = None
    for i, t in enumerate(toks):
        mo = _month_of(t) if re.fullmatch(r"[a-z]+", t) else None
        if (mo and t not in ("may",)) or (
            t == "may" and i > 0 and re.fullmatch(r"\d{1,2}", toks[i - 1] or "")
        ):
            month = mo
            if i > 0 and re.fullmatch(r"\d{1,2}", toks[i - 1]):
                day = int(toks[i - 1])
            elif i > 1 and toks[i - 1] == "of" and re.fullmatch(r"\d{1,2}", toks[i - 2]):
                day = int(toks[i - 2])
            elif i + 1 < len(toks) and re.fullmatch(r"\d{1,2}", toks[i + 1]):
                day = int(toks[i + 1])
            if i + 1 < len(toks) and re.fullmatch(r"\d{4}", toks[-1]):
                year = int(toks[-1])
    m = re.search(r"\b(\d{1,2})[/.](\d{1,2})(?:[/.](\d{2,4}))?\b", s)
    if month is None and m:
        day, month = int(m.group(1)), int(m.group(2))
        if m.group(3):
            year = int(m.group(3)) + (2000 if len(m.group(3)) == 2 else 0)
    if month and day:
        y = year or today.year
        d = _safe_date(y, month, day)
        if d and not year and d < today:
            d = _safe_date(y + 1, month, day)
        return (d.isoformat(), "date") if d else ("", "none")
    # weekday, with this / next
    for i, w in enumerate(_WDAYS):
        if re.search(r"\b" + w + r"\b", s):
            monday = today - datetime.timedelta(days=today.weekday())
            this_day = monday + datetime.timedelta(days=i)
            if re.search(r"\bnext\s+" + w, s) or "following" in s:
                d = this_day + datetime.timedelta(days=7)
            elif re.search(r"\bthis\s+" + w, s) or re.search(r"\bthis coming\s+" + w, s):
                d = this_day
            else:
                d = this_day if this_day >= today else this_day + datetime.timedelta(days=7)
            num = re.search(r"\b(\d{1,2})\b", s)
            if num:
                # 'Monday the 26th': trust the number, it is more specific
                n = int(num.group(1))
                dd = _safe_date(today.year, today.month, n) if 1 <= n <= 31 else None
                if dd and dd < today:
                    nm = today.month % 12 + 1
                    dd = _safe_date(today.year + (1 if nm == 1 else 0), nm, n)
                if dd:
                    return dd.isoformat(), "date"
            return d.isoformat(), "date"
    # 'the 26th' alone
    m = re.search(r"\b(?:the\s+)?(\d{1,2})\b", s)
    if (m and any(v in raw for v in ("the ",))) or (
        m and re.fullmatch(r"(?:on\s+)?(?:the\s+)?\d{1,2}", s)
    ):
        n = int(m.group(1))
        if 1 <= n <= 31:
            d = _safe_date(today.year, today.month, n)
            if d is None or d < today:
                nm = today.month % 12 + 1
                d = _safe_date(today.year + (1 if nm == 1 else 0), nm, n)
            if d:
                return d.isoformat(), "date"
    for v in _VAGUE:
        if v in raw:
            return "", "vague"
    return "", "none"


def parse_amount(text):
    """'637.50', '637,50', 'six hundred and thirty-seven fifty', 'two thousand one hundred
    twenty-five pounds and ten pence' -> float, or None."""
    raw = str(text or "").lower().replace("’", "'")
    raw = re.sub(r"(\d),(\d{2})(?!\d)", r"\1.\2", raw)
    if not raw.strip():
        return None
    s = _last_segment(raw)
    m = re.search(r"(\d[\d ,]*\d|\d)(?:[.,](\d{1,2}))?(?!\d)", s)
    if m and not re.search(
        r"[a-z]", re.sub(r"(pounds?|euros?|dollars?|eur|gbp|usd|and|cents?|pence|p\b)", "", s)
    ):
        whole = re.sub(r"[ ,]", "", m.group(1))
        frac = m.group(2) or ""
        try:
            return float(whole + ("." + frac if frac else ""))
        except Exception:
            return None
    s2 = re.sub(r"\b(pounds?|euros?|dollars?)\b", " | ", s)
    s2 = re.sub(r"\b(cents?|pence|p)\b", " ", s2)
    s2 = re.sub(r"\bpoint\b", " | ", s2)
    parts = [p for p in s2.split("|")]
    nums = []
    for p in parts:
        t = _words_to_number_tokens(p.replace("-", " "))
        found = re.findall(r"\d+(?:\.\d+)?", t)
        if found:
            nums.append(found)
    if not nums:
        return None
    try:
        whole = float(nums[0][0]) if len(nums[0]) == 1 else float("".join(nums[0]))
        if len(nums) > 1:
            cents = nums[1][0]
            if "point" in s and len(cents) == 1:
                return whole + float("0." + cents)
            return whole + float(cents) / 100.0
        if len(nums[0]) == 2 and float(nums[0][1]) < 100:
            # 'six hundred thirty seven fifty' -> 637.50
            return float(nums[0][0]) + float(nums[0][1]) / 100.0
        return whole
    except Exception:
        return None


def parse_spoken_time(text, day_start=10, day_end=19):
    """'around eleven', '11am', 'half past two', '14:30', 'two thirty in the afternoon' ->
    'HH:MM', or ''. A bare hour that cannot be a working hour as said (1 to 7) is read as
    afternoon; 'morning' / 'afternoon' / 'evening' / am / pm decide when given."""
    raw = str(text or "").lower().replace(".", " ").replace("-", " ")
    if not raw.strip():
        return ""
    s = re.sub(r"(\d)([a-z])", r"\1 \2", _last_segment(raw))
    if "noon" in s and "after" not in s:
        return "12:00"
    pm = bool(re.search(r"\b(pm|p m|afternoon|evening|tonight)\b", s))
    am = bool(re.search(r"\b(am|a m|morning)\b", s))
    s = re.sub(r"\b(o'?clock|oclock|ish|around|about|at|by|maybe)\b", " ", s)
    t = _words_to_number_tokens(s)
    hour, minute = None, 0
    m = re.search(r"\b(\d{1,2})[:h ](\d{2})\b", t)
    if m and int(m.group(2)) < 60:
        hour, minute = int(m.group(1)), int(m.group(2))
    else:
        m = re.search(r"\bhalf past (\d{1,2})\b", t)
        q = re.search(r"\bquarter past (\d{1,2})\b", t)
        q2 = re.search(r"\bquarter to (\d{1,2})\b", t)
        if m:
            hour, minute = int(m.group(1)), 30
        elif q:
            hour, minute = int(q.group(1)), 15
        elif q2:
            hour, minute = int(q2.group(1)) - 1, 45
        else:
            m = re.search(r"\b(\d{1,2}) (\d{2})\b", t)
            if m and int(m.group(2)) < 60 and int(m.group(1)) <= 23:
                hour, minute = int(m.group(1)), int(m.group(2))
            else:
                m = re.search(r"\b(\d{1,2})\b", t)
                if m:
                    hour = int(m.group(1))
    if hour is None or hour > 23:
        return ""
    if (pm and hour < 12) or (not am and 1 <= hour <= 7):
        hour += 12
    elif am and hour == 12:
        hour = 0
    return "%02d:%02d" % (hour, minute)


def digits_from_speech(text):
    """'four four seven one', '44 71', 'forty-four seventy-one' -> '4471'."""
    raw = str(text or "").lower().replace("-", " ")
    s = _last_segment(raw)
    out = []
    for w in re.findall(r"[a-z]+|\d+", s):
        if w.isdigit():
            out.append(w)
        elif w in ("oh", "o", "zero"):
            out.append("0")
        elif w in _UNITS:
            out.append(str(_UNITS[w]))
        elif w in _TENS:
            out.append(str(_TENS[w]))
        elif w in ("double", "triple"):
            out.append(w)
    # 'double four' -> '44'; 'forty four' -> '44' (a tens word followed by a unit)
    res = []
    i = 0
    while i < len(out):
        x = out[i]
        if x in ("double", "triple") and i + 1 < len(out):
            res.append(out[i + 1] * (2 if x == "double" else 3))
            i += 2
            continue
        if len(x) == 2 and x.endswith("0") and i + 1 < len(out) and len(out[i + 1]) == 1:
            res.append(x[0] + out[i + 1])
            i += 2
            continue
        res.append(x)
        i += 1
    return "".join(r for r in res if r.isdigit())


# Runs INSIDE Freya code nodes and in local tests, after collections_lib and speech_lib.
# Stdlib only, never raises to the caller, never two braces in a row.
#
# The negotiation as a state machine. The model only classifies the customer's reply
# (reply_kind) and copies the words of a date or an amount; this code decides what happens
# and writes the one instruction the model follows next (`say`). Every value that reaches the
# bank (product, amount, date, note reason, queue, outcome) is chosen here.
#
# NEG config (from the spec):
#   attempt_plan: [{"amount": "current"|"full"|"floor", "date": "attempt1"|"deadline"}, ...]
#   reasons: semantic -> bank reason name (refused, hardship, dispute, service_error, paid)
#   outcomes: semantic -> bank outcome name (promise, paid, transferred, no_promise)
#   queues: semantic (restructuring, human, support) -> queue name
#   transfer_reasons: semantic -> close reason
#   notes: true when products without a promise get add_note (Brief B)
#   lines: exact sentences (today_question, recorded, paid, sympathy, ...)
#   multi_today_question
#   policy knobs (POLICY_KEYS below): counts and choices a brief states. The builder must set
#   every one of them from the spec; POLICY_DEFAULTS only keeps a hand-run engine working and
#   `missing_policy` lets the builder refuse a config that would fall back to them.

# Brief A/B values. Never relied on by a generated workflow (see missing_policy).
POLICY_DEFAULTS = {
    # A42: ask once whether you can help, transfer on the second request. 1 = transfer at once.
    "human_requests_to_transfer": 2,
    # A45: close after the customer says twice that they do not want to talk.
    "stop_requests_to_close": 2,
    # A37: create_promise calls per product before giving up (first try + one retry).
    "promise_attempts": 2,
    # A37/B11 after the last failed call: "continue" (mark failed, close/note service_error)
    # or "transfer" (transfer to queue `record_failure_queue`).
    "record_failure": "continue",
    "record_failure_queue": "support",
    # A32: "offer_support" (offer a transfer; yes -> transfer, no -> hardship),
    # "transfer" (transfer at once) or "close" (no persuasion, close as hardship).
    "hardship": "offer_support",
    "hardship_queue": "support",
    # B closing: no promise recorded -> reason of the "first_product" (get_account order)
    # whose status is not paid, or the first status of `reason_priority` that any product has.
    "no_promise_reason": "first_product",
    "reason_priority": ["dispute", "hardship", "service_error", "refused"],
    # B10: add_note calls on a transferred call.
    "notes_on_transfer": False,
    # A21: times to ask for the exact day after a vague period, before proposing the deadline.
    "vague_date_asks": 1,
    # A26/A27: times the floor is offered after "too much" or an amount below the floor.
    "floor_offers": 1,
}
POLICY_KEYS = sorted(POLICY_DEFAULTS)


def _pol(neg, key):
    val = neg.get(key)
    return POLICY_DEFAULTS[key] if val is None else val


def missing_policy(neg):
    """Policy keys the config leaves to the defaults."""
    return [k for k in POLICY_KEYS if neg.get(k) is None]


SEMANTIC_KINDS = [
    "yes",
    "no",
    "offer",
    "too_much",
    "vague",
    "paid",
    "dispute",
    "hardship",
    "restructure",
    "human",
    "stop",
    "question",
    "unclear",
]


def _m(x):
    return money(x)


def _d(iso):
    return say_date(datetime.date.fromisoformat(iso)) if iso else ""


def _line(neg, key, default=""):
    return str((neg.get("lines") or {}).get(key) or default)


def new_state(pf, neg, now):
    """pf: product_facts output (pK_* keys)."""
    n = int(pf.get("product_count") or 0)
    ps = []
    for k in range(1, n + 1):
        key = "p" + str(k)
        try:
            full = float(pf.get(key + "_past_due") or 0)
        except Exception:
            full = 0.0
        try:
            floor = float(pf.get(key + "_floor") or 0) or full
        except Exception:
            floor = full
        try:
            att = int(pf.get(key + "_attempts") or 1)
        except Exception:
            att = 1
        ps.append(
            {
                "id": pf.get(key + "_id") or key,
                "name": pf.get(key + "_name") or "",
                "full": full,
                "floor": floor,
                "deadline": pf.get(key + "_deadline") or "",
                "days_late": pf.get(key + "_days_late") or "",
                "attempts": att,
                "used": 0,
                "too_much": False,
                "floor_offered": 0,
                "vague_asked": 0,
                "status": "open",
                "amount": None,
                "date": None,
                "offer": None,
                "own_deadline": False,
            }
        )
    st = {
        "phase": "ask_today",
        "i": 0,
        "p": ps,
        "human_asked": 0,
        "stop": 0,
        "transfer": "",
        "action": "say",
        "say": "",
        "rec": [],
        "rec_try": 0,
        "notes": [],
        "final_lines": [],
        "last_ask": "",
    }
    st["say"] = present_text(st, neg)
    st["last_ask"] = st["say"]
    return st


def present_text(st, neg):
    """The exact words that state every late product and ask the first question."""
    lines = []
    for p in st["p"]:
        lines.append(
            "Your "
            + p["name"]
            + " has "
            + _m(p["full"])
            + " past due and is "
            + str(_days(p))
            + " days late."
        )
    multi = len(st["p"]) > 1
    q = (
        _line(neg, "multi_today_question", "Can you pay all of them today?")
        if multi
        else _line(neg, "today_question", "Can you make this payment today?")
    )
    return " ".join(
        x
        for x in [_line(neg, "present_intro", "I am calling about a late payment.")] + lines + [q]
        if x
    )


def _rest(neg):
    return _line(neg, "rest_overdue", "The rest stays overdue.")


def _days(p):
    return p.get("days_late", "") if p.get("days_late") not in (None, "") else ""


def _current_amount(p):
    return p["floor"] if p["too_much"] else p["full"]


def _attempt_offer(st, k, neg, cal):
    p = st["p"][k]
    plan = neg.get("attempt_plan") or [
        {"amount": "current", "date": "attempt1"},
        {"amount": "floor", "date": "deadline"},
    ]
    step = plan[min(p["used"], len(plan)) - 1]
    amount = (
        p["floor"]
        if step.get("amount") == "floor"
        else (p["full"] if step.get("amount") == "full" else _current_amount(p))
    )
    date = p["deadline"] if step.get("date") == "deadline" else cal.get("attempt1_date", "")
    if date and p["deadline"] and date > p["deadline"]:
        date = p["deadline"]
    p["offer"] = {"amount": amount, "date": date, "kind": "attempt"}
    floor_note = ""
    if amount < p["full"] - 0.005:
        floor_note = " " + _rest(neg)
    return (
        "Could you pay "
        + _m(amount)
        + " for the "
        + p["name"]
        + " on "
        + _d(date)
        + "?"
        + floor_note
    )


def _flat_refusal(st, k, neg, cal):
    p = st["p"][k]
    if p["used"] < p["attempts"]:
        p["used"] += 1
        return _attempt_offer(st, k, neg, cal)
    p["status"] = "refused"
    p["offer"] = None
    return None


def _agree(p, amount, date, own_deadline=False):
    p["status"] = "agreed"
    p["amount"] = round(float(amount), 2)
    p["date"] = date
    p["offer"] = None
    p["own_deadline"] = own_deadline


def _apply_offer(st, k, amount, date_iso, date_kind, neg, cal, now, cfg, all_products):
    """The customer named an amount and/or a date for product k (or for all)."""
    p = st["p"][k]
    targets = (
        [j for j, q in enumerate(st["p"]) if q["status"] in ("open", "agreed")]
        if all_products
        else [k]
    )
    if amount is None:
        amount = p["offer"]["amount"] if p.get("offer") else _current_amount(p)
    if amount > p["full"] + 0.005:
        amount = p["full"]
    if amount < p["floor"] - 0.005 and len(targets) == 1:
        if p["floor_offered"] >= _pol(neg, "floor_offers"):
            return _flat_refusal(st, k, neg, cal)
        p["floor_offered"] += 1
        d = date_iso or (p["offer"] or {}).get("date") or cal.get("today_iso")
        p["offer"] = {"amount": p["floor"], "date": d, "kind": "floor"}
        return (
            "I cannot record "
            + _m(amount)
            + ". The minimum is "
            + _m(p["floor"])
            + ". Could you pay "
            + _m(p["floor"])
            + " on "
            + _d(d)
            + "? "
            + _rest(neg)
        )
    if not date_iso:
        if date_kind == "vague":
            if p["vague_asked"] < _pol(neg, "vague_date_asks"):
                p["vague_asked"] += 1
                p["pending_amount"] = amount
                return _line(neg, "vague_ask", "On which exact day will you pay?")
            p["offer"] = {"amount": amount, "date": p["deadline"], "kind": "deadline"}
            return (
                "The latest date I can record is "
                + _d(p["deadline"])
                + ". Could you pay "
                + _m(amount)
                + " on that day?"
            )
        if p.get("offer") and p["offer"].get("date"):
            date_iso = p["offer"]["date"]
        else:
            p["pending_amount"] = amount
            return "On which day can you pay " + _m(amount) + "?"
    said = []
    for j in targets:
        q = st["p"][j]
        amt = amount if j == k else (q["amount"] if q["status"] == "agreed" else _current_amount(q))
        res = check_promise_date(date_iso, q["deadline"], now, cfg)
        if res == "ok":
            _agree(q, amt, date_iso)
        elif res.startswith("after_deadline") and len(targets) > 1:
            _agree(q, amt, q["deadline"], own_deadline=True)
        elif res.startswith("after_deadline"):
            q["offer"] = {"amount": amt, "date": q["deadline"], "kind": "deadline"}
            said.append(
                "The latest date I can record for the "
                + q["name"]
                + " is "
                + _d(q["deadline"])
                + ". Could you pay "
                + _m(amt)
                + " on that day?"
            )
        elif res.startswith("not_business_day"):
            nb = res.split(":", 1)[1]
            q["offer"] = {"amount": amt, "date": nb, "kind": "next_business_day"}
            said.append(
                _d(date_iso)
                + " is not a business day. Could you pay "
                + _m(amt)
                + " on the next business day, "
                + _d(nb)
                + "?"
            )
        elif res == "past":
            said.append("The date has to be today or later. On which day can you pay?")
        else:
            said.append("On which exact day can you pay?")
        if said:
            st["i"] = j
            return said[0]
    return None


def _next_open(st):
    for j, q in enumerate(st["p"]):
        if q["status"] == "open":
            return j
    return -1


def _readback(st, neg):
    parts = []
    for q in st["p"]:
        if q["status"] == "agreed":
            parts.append(
                "the "
                + q["name"]
                + ", "
                + _m(q["amount"])
                + " on "
                + _d(q["date"])
                + (
                    ", which is the latest date I can record for it"
                    if q.get("own_deadline")
                    else ""
                )
            )
    return (
        "To confirm: " + "; ".join(parts) + ". " + _line(neg, "confirm_question", "Do you confirm?")
    )


def _advance(st, neg, cal):
    """Move to the next open product, to the read-back, or to the end."""
    j = _next_open(st)
    if j >= 0:
        ack = ""
        just = [q for q in st["p"] if q["status"] == "agreed" and not q.get("acked")]
        if just:
            ack = (
                "I have noted "
                + ", ".join(
                    "the " + q["name"] + " for " + _m(q["amount"]) + " on " + _d(q["date"])
                    for q in just
                )
                + ". "
            )
            for q in just:
                q["acked"] = True
        st["i"] = j
        st["phase"] = "offer"
        p = st["p"][j]
        if p["used"] == 0:
            p["used"] = 1
        return ack + _attempt_offer(st, j, neg, cal)
    if any(q["status"] == "agreed" for q in st["p"]):
        st["phase"] = "confirm"
        return _readback(st, neg)
    return None


def _finish(st, neg):
    st["action"] = "finish"
    oc = neg.get("outcomes") or {}
    rs = neg.get("reasons") or {}
    sem = {
        "refused": "refused",
        "open": "refused",
        "hardship": "hardship",
        "dispute": "dispute",
        "failed": "service_error",
        "paid": "paid",
    }
    notes = []
    for q in st["p"]:
        if q["status"] != "recorded":
            s = sem.get(q["status"], "refused")
            notes.append([q["id"], rs.get(s, s)])
    st["notes"] = notes if neg.get("notes") else []
    if st["transfer"]:
        st["final_outcome"] = oc.get("transferred", "transferred")
        st["final_reason"] = (neg.get("transfer_reasons") or {}).get(st["transfer"], st["transfer"])
        if not _pol(neg, "notes_on_transfer"):
            st["notes"] = []
        return
    if any(q["status"] == "recorded" for q in st["p"]):
        st["final_outcome"] = oc.get("promise", "promise")
        st["final_reason"] = ""
        return
    left = [sem.get(q["status"], "refused") for q in st["p"] if q["status"] != "paid"]
    if not left:
        st["final_outcome"] = oc.get("paid", "paid")
        st["final_reason"] = ""
        return
    st["final_outcome"] = oc.get("no_promise", "no_promise")
    s = left[0]
    if _pol(neg, "no_promise_reason") == "priority":
        s = next((x for x in _pol(neg, "reason_priority") if x in left), left[0])
    st["final_reason"] = rs.get(s, s)


def _transfer(st, what, neg):
    st["transfer"] = what
    st["transfer_queue"] = (neg.get("queues") or {}).get(what, what)
    # Brief B rule 10: agreed but unrecorded promises are dropped.
    for q in st["p"]:
        if q["status"] == "agreed":
            q["status"] = "open"
    st["final_lines"].append(
        _line(neg, "transfer_" + what, "I am connecting you with a colleague now.")
    )
    _finish(st, neg)
    st["action"] = "transfer"


def _close_hardship(st, neg):
    for q in st["p"]:
        if q["status"] in ("open", "agreed"):
            q["status"] = "hardship"
    _finish(st, neg)


def step(st, r, neg, cal, now, cfg):
    """r: {kind, amount, date, date_kind, all, product}. Mutates and returns st."""
    st["action"] = "say"
    st["mode"] = "speak"
    kind = r.get("kind") or "unclear"
    k = st["i"]
    # A product the customer names counts only while it is still open (extraction is noisy).
    if (
        r.get("product") is not None
        and 0 <= r["product"] < len(st["p"])
        and st["p"][r["product"]]["status"] in ("open", "agreed")
    ):
        k = r["product"]
    say = None
    phase = st["phase"]
    if kind == "restructure":
        _transfer(st, "restructuring", neg)
        return st
    if kind == "human":
        st["human_asked"] += 1
        if st["human_asked"] < _pol(neg, "human_requests_to_transfer"):
            st["say"] = _line(
                neg, "help_first", "Before I transfer you, can I help you with this myself?"
            )
            return st
        _transfer(st, "human", neg)
        return st
    if phase == "hardship_offer":
        if kind == "yes":
            _transfer(st, _pol(neg, "hardship_queue"), neg)
            return st
        if kind != "offer":
            _close_hardship(st, neg)
            return st
        phase = "offer"
    elif kind == "hardship":
        mode = _pol(neg, "hardship")
        if mode == "transfer":
            st["final_lines"].append(_line(neg, "sympathy"))
            _transfer(st, _pol(neg, "hardship_queue"), neg)
            return st
        if mode == "close":
            st["final_lines"].append(_line(neg, "sympathy"))
            _close_hardship(st, neg)
            return st
        st["phase"] = "hardship_offer"
        st["say"] = (
            _line(neg, "sympathy", "I am sorry to hear that.")
            + " "
            + _line(
                neg,
                "support_offer",
                "Would you like me to connect you with our customer support team?",
            )
        )
        return st
    if kind == "stop":
        st["stop"] += 1
        if st["stop"] >= _pol(neg, "stop_requests_to_close"):
            for q in st["p"]:
                if q["status"] in ("open", "agreed"):
                    q["status"] = "refused"
            _finish(st, neg)
            return st
        st["say"] = "I understand. " + st["last_ask"]
        return st
    if kind in ("paid", "dispute"):
        p = st["p"][k]
        p["status"] = kind
        p["offer"] = None
        if kind == "paid":
            st["final_lines"].append(
                _line(neg, "paid", "Payments can take one business day to appear.")
            )
        say = _advance(st, neg, cal) if len(st["p"]) > 1 else None
        if say is None:
            _finish(st, neg)
            return st
        pre = (
            _line(neg, "paid", "Payments can take one business day to appear.")
            if kind == "paid"
            else _line(neg, "dispute_noted", "I have noted that.")
        )
        st["say"] = pre + " " + say
        st["last_ask"] = say
        return st
    if kind == "question":
        st["mode"] = "llm"
        st["say"] = (
            "Answer the customer's last question in one short sentence, only with what you "
            "know from this call; if you do not have the information, say so. Then say "
            'exactly: "' + st["last_ask"] + '"'
        )
        return st
    if phase == "closing":
        _finish(st, neg)
        return st
    if phase == "confirm":
        if kind == "yes":
            st["rec"] = [j for j, q in enumerate(st["p"]) if q["status"] == "agreed"]
            st["rec_try"] = 0
            st["action"] = "record"
            st["phase"] = "recording"
            _set_rec(st)
            return st
        if kind == "offer":
            agreed = [j for j, q in enumerate(st["p"]) if q["status"] == "agreed"]
            j = k if k in agreed else (agreed[0] if agreed else k)
            say = _apply_offer(
                st,
                j,
                r.get("amount"),
                r.get("date"),
                r.get("date_kind"),
                neg,
                cal,
                now,
                cfg,
                bool(r.get("all")) and len(agreed) > 1,
            )
            st["say"] = say or _readback(st, neg)
            if say is None:
                st["phase"] = "confirm"
            st["last_ask"] = st["say"]
            return st
        if kind == "no":
            agreed = [j for j, q in enumerate(st["p"]) if q["status"] == "agreed"]
            if len(agreed) == 1:
                j = agreed[0]
                st["p"][j]["status"] = "open"
                say = _flat_refusal(st, j, neg, cal)
                if say is None:
                    say = _advance(st, neg, cal)
                if say is None:
                    _finish(st, neg)
                    return st
                st["phase"] = "offer" if st["p"][j]["status"] == "open" else st["phase"]
                st["say"] = say
                st["last_ask"] = say
                return st
            st["say"] = "Which promise would you like to change?"
            return st
        st["say"] = _readback(st, neg)
        return st
    # ask_today or offer
    p = st["p"][k]
    multi = len(st["p"]) > 1
    if kind == "yes":
        if phase == "ask_today":
            for q in st["p"]:
                if q["status"] == "open":
                    res = check_promise_date(cal.get("today_iso"), q["deadline"], now, cfg)
                    d = (
                        cal.get("today_iso")
                        if res == "ok"
                        else (res.split(":", 1)[1] if ":" in res else q["deadline"])
                    )
                    _agree(q, q["full"], d)
        elif p.get("offer"):
            o = p["offer"]
            _agree(p, o["amount"], o["date"])
        else:
            st["say"] = st["last_ask"]
            return st
        say = _advance(st, neg, cal)
    elif kind == "no":
        say = _flat_refusal(st, k, neg, cal)
        if say is None:
            say = _advance(st, neg, cal)
        else:
            st["phase"] = "offer"
    elif kind == "offer" or (kind == "vague"):
        amount = r.get("amount")
        say = _apply_offer(
            st,
            k,
            amount,
            r.get("date"),
            "vague" if kind == "vague" else r.get("date_kind"),
            neg,
            cal,
            now,
            cfg,
            multi
            and amount is None
            and (bool(r.get("all")) or (phase == "ask_today" and r.get("product") is None)),
        )
        if say is None:
            say = _advance(st, neg, cal)
        else:
            st["phase"] = "offer"
    elif kind == "too_much":
        if not p["too_much"]:
            p["too_much"] = True
        if p["floor_offered"] < _pol(neg, "floor_offers") and p["floor"] < p["full"] - 0.005:
            p["floor_offered"] += 1
            d = (p.get("offer") or {}).get("date") or cal.get("today_iso")
            p["offer"] = {"amount": p["floor"], "date": d, "kind": "floor"}
            say = (
                "The minimum for the "
                + p["name"]
                + " is "
                + _m(p["floor"])
                + ". Could you pay "
                + _m(p["floor"])
                + " on "
                + _d(d)
                + "? "
                + _rest(neg)
            )
            st["phase"] = "offer"
        else:
            say = _flat_refusal(st, k, neg, cal)
            if say is None:
                say = _advance(st, neg, cal)
            else:
                st["phase"] = "offer"
    else:
        st["say"] = "Sorry, I did not get that. " + st["last_ask"]
        return st
    if say is None:
        _finish(st, neg)
        return st
    st["say"] = say
    st["last_ask"] = say
    return st


def _set_rec(st):
    if st["rec"]:
        q = st["p"][st["rec"][0]]
        st["rec_product_id"] = q["id"]
        st["rec_amount"] = q["amount"]
        st["rec_date"] = q["date"]


def record_result(st, ok, neg, cal):
    """After one create_promise call. Retries up to `promise_attempts` calls in total, then
    marks the product failed (and transfers when `record_failure` says so)."""
    j = st["rec"][0]
    q = st["p"][j]
    if ok:
        q["status"] = "recorded"
        st["rec"].pop(0)
        st["rec_try"] = 0
    else:
        st["rec_try"] += 1
        if st["rec_try"] >= int(_pol(neg, "promise_attempts")):
            q["status"] = "failed"
            st["rec"].pop(0)
            st["rec_try"] = 0
            if _pol(neg, "record_failure") == "transfer":
                st["rec"] = []
                _transfer(st, _pol(neg, "record_failure_queue"), neg)
                return st
    if st["rec"]:
        st["action"] = "record"
        _set_rec(st)
        return st
    rec = [q for q in st["p"] if q["status"] == "recorded"]
    bad = [q for q in st["p"] if q["status"] == "failed"]
    parts = []
    if rec:
        parts.append(
            "Your promise is recorded: "
            + "; ".join(
                "the " + q["name"] + ", " + _m(q["amount"]) + " on " + _d(q["date"]) for q in rec
            )
            + ". "
            + _line(neg, "recorded", "You will receive a text message confirming this promise.")
        )
    if bad:
        parts.append(
            "I could not record the promise for the " + ", the ".join(q["name"] for q in bad) + "."
        )
    anything = _line(neg, "anything_else", "Is there anything else I can help you with?")
    parts.append(anything)
    st["action"] = "say"
    st["mode"] = "speak"
    st["phase"] = "closing"
    st["say"] = " ".join(parts)
    st["last_ask"] = anything
    return st


def final_say(st, neg):
    lines = list(st.get("final_lines") or [])
    lines.append(_line(neg, "goodbye", "Thank you for your time. Goodbye."))
    return " ".join(x for x in lines if x)


